{
  "scenario_id": "sc-e28a00",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2016, 2019],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.02/yr, peaking at A/E 1.15",
      "confidence": 0.75,
      "evidence": [
        "ae_death_by_year.csv: A/E rises monotonically from 1.025 (2016) to 1.149 (2019), with three consecutive years >1.10; exceeds expected Poisson noise (~4-5% SD) for claim counts of 290-447, followed by a reversion to 0.94-0.99 in 2020-2024"
      ],
      "recommended_action": "Investigate underwriting standards, new business mix, and claims coding changes during 2016-2019; review mortality table alignment and consider targeted pricing/assumption updates if the trend persists in newer vintages."
    },
    {
      "benefit": "TPD",
      "years": [2020, 2021],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "A/E spikes to 1.19-1.22 (+0.20 above baseline)",
      "confidence": 0.9,
      "evidence": [
        "ae_tpd_by_year.csv: abrupt two-year level shift in 2020-2021 (A/E 1.221, 1.187) with expected claims ~826-897; magnitude far exceeds Poisson expectation (~3.5% SD); reverts to ~0.94-0.95 in 2022-2024"
      ],
      "recommended_action": "Conduct deep-dive into 2020-2021 claims drivers (e.g., pandemic impact, underwriting lapse, specific employer/broker block); assess valuation and pricing sensitivity to this excursion; monitor subsequent years to confirm reversion stability."
    }
  ]
}

